const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Math.abs(x)<1e-9?'0':Number(x.toFixed(4)).toString();
const math=t=>`<span class="sl-math" data-math-source="${esc(t)}">${mathHTML(t)}</span>`;
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0),T=a=>a[0].map((_,j)=>a.map(r=>r[j])),mm=(a,b)=>a.map(r=>T(b).map(c=>dot(r,c))),eye=n=>Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j?1:0)),scale=(a,s)=>a.map(r=>r.map(x=>x*s)),sum=(items,n)=>items.reduce((a,b)=>a.map((r,i)=>r.map((x,j)=>x+b[i][j])),eye(n).map(r=>r.map(()=>0))),err=(a,b)=>Math.max(...a.flatMap((r,i)=>r.map((x,j)=>Math.abs(x-b[i][j])))),trace=a=>a.reduce((s,r,i)=>s+r[i],0),comm=(a,b)=>err(mm(a,b),mm(b,a));
const names=['e','(12)','(23)','(13)','(123)','(132)'],perms=[[0,1,2],[1,0,2],[0,2,1],[2,1,0],[1,2,0],[2,0,1]],classes=[[0],[1,2,3],[4,5]],sizes=[1,3,2],chars={A1:[1,1,1],A2:[1,-1,1],E:[2,0,-1]},dims={A1:1,A2:1,E:2};
const mult=perms.map(a=>perms.map(b=>perms.findIndex(c=>c.every((v,j)=>v===a[b[j]])))),inverse=mult.map(row=>row.indexOf(0));
const matrices=perms.map(p=>Array.from({length:3},(_,i)=>Array.from({length:3},(_,j)=>p[j]===i?1:0))),u=[2,-1,-1].map(x=>x/Math.sqrt(6)),v=[0,1,-1].map(x=>x/Math.sqrt(2)),basis=u.map((x,i)=>[x,v[i]]),em=matrices.map(d=>mm(mm(T(basis),d),basis)),PA=Array.from({length:3},()=>[1/3,1/3,1/3]),PE=PA.map((r,i)=>r.map((x,j)=>(i===j?1:0)-x));
const rep=name=>name==='permutation'?matrices:name==='E'?em:name==='A1'?names.map(()=>[[1]]):names.map((_,i)=>[[[0,4,5].includes(i)?1:-1]]);
const inv2=a=>{const d=a[0][0]*a[1][1]-a[0][1]*a[1][0];return [[a[1][1]/d,-a[0][1]/d],[-a[1][0]/d,a[0][0]/d]];};
export const theoremThemes=[{id:'rearrangement',title:"Rearrangement theorem"},{id:'conjugacy',title:"Conjugacy and conjugacy classes"},{id:'normal',title:"Normal subgroups and quotient groups"},{id:'irreducible',title:"Reducible and irreducible representations"},{id:'schur',title:"Schur's lemma"},{id:'unitarity',title:"Unitarizing finite-group representations"},{id:'orthogonality',title:"Great orthogonality theorem"},{id:'reduction',title:"Character reduction and dimensions"},{id:'degeneracy',title:"Symmetry and energy-level degeneracy"}];
const defaults={rearrangement:{h:1,side:'left'},conjugacy:{g:1,h:4},normal:{subgroup:'A3',h:2},irreducible:{representation:'permutation',g:4},schur:{representation:'permutation',a:.4,b:1.1},unitarity:{scale:1.8,shear:.6,g:4,metric:'average'},orthogonality:{alpha:'E',beta:'E',i:0,j:0,k:0,l:0},reduction:{preset:'permutation',chiE:3,chiT:1,chiC:0},degeneracy:{a:-.5,b:.5,epsilon:0}};
let latest=null;
export const getGroupTheoremsResult=()=>latest;

export function theoremPreview(experiment,params={}){
 const p={...defaults[experiment],...params};
 if(experiment==='rearrangement'){const images=names.map((_,g)=>p.side==='left'?mult[p.h][g]:mult[g][p.h]);return {h:p.h,side:p.side,images,multiplicationTable:mult,inverse:inverse[p.h]};}
 if(experiment==='conjugacy'){const conjugate=mult[mult[p.h][p.g]][inverse[p.h]];return {g:p.g,h:p.h,inverse:inverse[p.h],conjugate,classIndex:classes.findIndex(c=>c.includes(p.g)),selectedMatrix:matrices[p.g],conjugateMatrix:matrices[conjugate]};}
 if(experiment==='normal'){
  const subgroup=p.subgroup==='A3'?[0,4,5]:[0,1],conj=g=>subgroup.map(x=>mult[mult[g][x]][inverse[g]]).sort((a,b)=>a-b),normal=names.every((_,g)=>JSON.stringify(conj(g))===JSON.stringify(subgroup)),leftCosets=[],rightCosets=[];
  names.forEach((_,g)=>{for(const [store,c] of [[leftCosets,subgroup.map(x=>mult[g][x]).sort((a,b)=>a-b)],[rightCosets,subgroup.map(x=>mult[x][g]).sort((a,b)=>a-b)]])if(!store.some(q=>JSON.stringify(q)===JSON.stringify(c)))store.push(c);});
  return {subgroupName:p.subgroup,subgroup,h:p.h,conjugated:conj(p.h),normal,leftCosets,rightCosets,quotientTable:normal?leftCosets.map(a=>leftCosets.map(b=>leftCosets.findIndex(c=>c.includes(mult[a[0]][b[0]])))):null};
 }
 if(experiment==='irreducible'){const ds=rep(p.representation),cs=classes.map(c=>trace(ds[c[0]])),characterNorm=dot(sizes,cs.map(x=>x*x))/6;return {representation:p.representation,g:p.g,selectedMatrix:ds[p.g],representationCharacters:cs,characterNorm,irreducible:Math.abs(characterNorm-1)<1e-9};}
 if(experiment==='schur'){const ds=rep(p.representation),intertwiner=p.representation==='E'?scale(eye(2),p.a):sum([scale(PA,p.a),scale(PE,p.b)],3);return {intertwiner,scalar:p.representation==='E'||Math.abs(p.a-p.b)<1e-12,commutatorResidual:Math.max(...ds.map(d=>comm(intertwiner,d)))};}
 if(experiment==='unitarity'){
  const S=[[p.scale,p.shear],[0,1]],ds=em.map(d=>mm(mm(inv2(S),d),S)),metric=mm(T(S),S),averagedMetric=scale(sum(ds.map(d=>mm(T(d),d)),2),1/6),chosenMetric=p.metric==='average'?averagedMetric:metric,a=Math.sqrt(chosenMetric[0][0]),b=chosenMetric[0][1]/a,c=Math.sqrt(chosenMetric[1][1]-b*b),factor=[[a,b],[0,c]],us=ds.map(d=>mm(mm(factor,d),inv2(factor)));
  return {S,nonunitary:ds[p.g],metric,averagedMetric,chosenMetric,factor,unitary:us[p.g],ordinaryResidual:Math.max(...ds.map(d=>err(mm(T(d),d),eye(2)))),metricResidual:Math.max(...ds.map(d=>err(mm(mm(T(d),chosenMetric),d),chosenMetric))),unitaryResidual:Math.max(...us.map(d=>err(mm(T(d),d),eye(2))))};
 }
 if(experiment==='orthogonality'){
  const da=rep(p.alpha),db=rep(p.beta),terms=da.map((d,g)=>d[p.i][p.j]*db[g][p.k][p.l]),expected=p.alpha===p.beta&&p.i===p.k&&p.j===p.l?6/dims[p.alpha]:0;return {terms,total:terms.reduce((a,b)=>a+b,0),expected,characterInner:dot(sizes,chars[p.alpha].map((x,i)=>x*chars[p.beta][i]))/6};
 }
 if(experiment==='reduction'){
  const inputCharacters=p.preset==='custom'?[p.chiE,p.chiT,p.chiC]:({permutation:[3,1,0],regular:[6,0,0],E:[2,0,-1]})[p.preset],weightedTerms=Object.fromEntries(Object.entries(chars).map(([name,row])=>[name,row.map((x,i)=>x*inputCharacters[i]*sizes[i])])),multiplicities=Object.fromEntries(Object.entries(weightedTerms).map(([name,terms])=>[name,terms.reduce((a,b)=>a+b,0)/6]));
  return {inputCharacters,weightedTerms,multiplicities,validCharacter:Object.values(multiplicities).every(x=>x>=-1e-10&&Math.abs(x-Math.round(x))<1e-9),reconstructedDimension:Object.entries(multiplicities).reduce((sum,[name,m])=>sum+dims[name]*m,0),dimensionSquaredSum:6,classCount:3};
 }
 if(experiment==='degeneracy'){
  const hamiltonian=sum([scale(PA,p.a),scale(PE,p.b),u.map(x=>u.map(y=>p.epsilon*x*y))],3),commutatorResidual=Math.max(...matrices.map(d=>comm(hamiltonian,d)));return {hamiltonian,levels:[{basis:'A1',energy:p.a,irrep:'A1'},{basis:'u',energy:p.b+p.epsilon,irrep:'E'},{basis:'v',energy:p.b,irrep:'E'}],commutatorResidual,fullSymmetry:commutatorResidual<1e-9,protectedE:Math.abs(p.epsilon)<1e-12,accidentalThreefold:Math.abs(p.a-p.b)<1e-12&&Math.abs(p.epsilon)<1e-12};
 }
 throw new Error("Unknown group-theory topic");
}

const table=(heads,rows)=>`<div class="gt-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const matrix=a=>`<div class="gt-matrix" style="--gt-cols:${a[0].length}">${a.flatMap(r=>r.map(x=>`<span>${fmt(x)}</span>`)).join('')}</div>`;
const text=(x,y,value,color='#183c52',size=17)=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" text-anchor="middle">${esc(value)}</text>`;
const line=(x,y,a,b,color='#7c96a6',w=2)=>`<line x1="${x}" y1="${y}" x2="${a}" y2="${b}" stroke="${color}" stroke-width="${w}"/>`;
const svg=(label,body)=>`<svg viewBox="0 0 660 330" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${body}</svg>`;
const exercise=(q,steps)=>`<section class="gt-exercise"><h3>Predict first, then check step by step</h3><p>${q}</p><details><summary>Show derivation and conditions</summary><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol></details></section>`;
const select=(id,label,value,options)=>`<label><span>${label}</span><select data-param="${id}" aria-label="${esc(label)}">${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const range=(id,label,v,min,max,step)=>`<label><span>${label} <output data-output="${id}">${v}</output></span><input type="range" aria-label="${esc(label)}" data-param="${id}" value="${v}" min="${min}" max="${max}" step="${step}"></label>`;
const elementOptions=names.map((name,i)=>[i,name]),repOptions=[['permutation',"Permutation representation on three vertices"],['E',"Two-dimensional complex irrep E"],['A1',"One-dimensional A₁"],['A2',"One-dimensional A₂"]];
const setLabel=indices=>'{'+indices.map(i=>names[i]).join(', ')+'}';
function controls(t,p){
 if(t==='rearrangement')return select('h',"Fixed multiplier h",p.h,elementOptions)+select('side',"Multiplication side",p.side,[['left',"Left multiplication: h g"],['right',"Right multiplication: g h"]]);
 if(t==='conjugacy')return select('g',"Element g to conjugate",p.g,elementOptions)+select('h',"Element h changing the description",p.h,elementOptions);
 if(t==='normal')return select('subgroup',"Subgroup to test",p.subgroup,[['A3','A₃ = {e,(123),(132)}'],['H12','H = {e,(12)}']])+select('h',"Choose the conjugating element h",p.h,elementOptions);
 if(t==='irreducible')return select('representation',"Representation space",p.representation,repOptions)+select('g',"Inspect the matrix of one operation",p.g,elementOptions);
 if(t==='schur')return select('representation',"Representation space",p.representation,repOptions.slice(0,2))+range('a',"Scalar a for the A₁ block / single E block",p.a,-2,2,.05)+range('b',"Scalar b for the E block in the reducible representation",p.b,-2,2,.05);
 if(t==='unitarity')return range('scale',"Similarity-transform scaling s",p.scale,.4,3,.05)+range('shear',"Similarity-transform shear c",p.shear,-1.5,1.5,.05)+select('g',"Group operation to inspect",p.g,elementOptions)+select('metric',"Source of the positive-definite inner product",p.metric,[['average',"Average D†D over the whole group"],['similarity',"Known S†S"]]);
 if(t==='orthogonality')return select('alpha',"Representation α",p.alpha,repOptions.slice(1))+select('beta',"Representation β",p.beta,repOptions.slice(1))+['i','j','k','l'].map(key=>select(key,`Matrix index ${key}(one-based)`,p[key],Array.from({length:dims[['i','j'].includes(key)?p.alpha:p.beta]},(_,n)=>[n,String(n+1)]))).join('');
 if(t==='reduction')return select('preset',"Characters to reduce",p.preset,[['permutation',"Three-vertex permutation: χ=(3,1,0)"],['regular',"Regular representation: χ=(6,0,0)"],['E',"Two-dimensional E: χ=(2,0,−1)"],['custom',"Propose your own candidate characters"]])+(p.preset==='custom'?range('chiE',"Identity-class χ(e)",p.chiE,0,12,1)+range('chiT',"χ for the transposition class",p.chiT,-6,6,1)+range('chiC',"χ for the three-cycle class",p.chiC,-6,6,1):'');
 return range('a',"A₁-subspace energy a",p.a,-2,2,.05)+range('b',"E-subspace energy b",p.b,-2,2,.05)+range('epsilon',"E-partner symmetry-breaking term ε",p.epsilon,-1,1,.025);
}

function scene(t,p){
 const r=theoremPreview(t,p);let body='',html='',task;
 if(t==='rearrangement'){
  names.forEach((name,i)=>{const x=65+i*104,y=65+r.images[i]*0;body+=`<rect x="${x-40}" y="65" width="80" height="43" rx="6" fill="#edf4f8" stroke="#93aebd"/>`+text(x,92,name)+line(x,112,65+r.images[i]*104,235,'#4e8ba6',2)+text(65+i*104,267,names[i]);});
  html=`<h3>A fixed multiplier gives a bijective rearrangement of the group elements</h3><p>${math(p.side==='left'?String.raw`g\mapsto hg`:String.raw`g\mapsto gh`)}, with fixed h=${esc(names[p.h])}. The output order is ${esc(r.images.map(i=>names[i]).join(', '))}; all 6 elements appear exactly once.</p><p>Group multiplication acts bijectively on the set of group elements, without requiring commutativity. The inverse map uses ${math(String.raw`h^{-1}`)}=${esc(names[r.inverse])}。</p>`;
  task=exercise("Does switching the multiplication side change the rearrangement? Does it change bijectivity?",["In a noncommutative group, left and right multiplication can give different orders.","If hg₁=hg₂, left multiplication by the inverse of h gives g₁=g₂. The right-multiplication case is analogous.","An injection of a finite set into itself is also surjective. The result therefore rearranges elements without losing or repeating any."]);
 }
 if(t==='conjugacy'){
  classes.forEach((members,j)=>{const x=20+j*215;body+=`<rect x="${x}" y="60" width="200" height="225" rx="12" fill="#f2f7fa" stroke="#a2b8c5"/>`+text(x+100,90,["Identity class","Transposition class","Three-cycle class"][j]);members.forEach((g,i)=>{body+=text(x+100,135+i*52,names[g],g===r.conjugate?'#ad6130':g===p.g?'#237a9c':'#35556a',20);});});
  html=`<h3>${math(String.raw`hgh^{-1}`)}=${esc(names[r.conjugate])}, still in the same conjugacy class</h3><p>Current g=${esc(names[p.g])}，h=${esc(names[p.h])}. Conjugation relabels a description through a group transformation. The representation matrices of conjugate operations are similar and hence have equal traces.</p><p>Every experiment on this page orders elements as e, three transpositions, then two three-cycles. Class sizes are 1,3,2. This differs from the E,2C₃,3C₂ column order used in the earlier D₃ lesson.</p>`;
  task=exercise("Must any two elements of the same order be conjugate? How general a conclusion does this example support?",["Conjugation preserves order because (hgh⁻¹)ⁿ=hgⁿh⁻¹.","In S₃, the three transpositions do form one conjugacy class, and the two three-cycles form another.","Equal order is necessary for conjugacy in a general group, but is not sufficient. This small example's classification cannot be extended to every group."]);
 }
 if(t==='normal'){
  r.leftCosets.forEach((c,i)=>{const x=30+i*210;body+=`<rect x="${x}" y="75" width="190" height="110" rx="12" fill="#eef5f8" stroke="#8babbc"/>`+text(x+95,108,`Left coset ${i+1}`)+text(x+95,148,setLabel(c),undefined,13);});body+=text(330,239,'h H h⁻¹ = '+setLabel(r.conjugated),undefined,18)+text(330,285,r.normal?"equals H for every h: normal":"some h changes the conjugate set: not normal",r.normal?'#26786d':'#a85e34');
  html=`<h3>${r.normal?"Normal subgroup: a quotient group can be constructed":"Nonnormal subgroup: cosets exist, but do not directly form a quotient group"}</h3><p>H=${esc(setLabel(r.subgroup))}. The conjugate set for current h=${esc(names[p.h])} is shown above. Normality must still be checked for every h, rather than one selected example.</p>${table(["Left coset","Right coset"],r.leftCosets.map((c,i)=>[esc(setLabel(c)),esc(setLabel(r.rightCosets[i]))]))}${r.normal?`<p>The quotient-group product is defined by multiplying representatives of the two cosets, independently of the representatives chosen.</p>${table(["Multiplication",'H',"Other coset"],r.quotientTable.map((row,i)=>[i?"Other coset":'H',...row.map(x=>x?"Other coset":'H')]))}`:"<p>For a nonnormal subgroup, representative multiplication does not give a well-defined group operation on cosets. Having left cosets alone does not establish a quotient group.</p>"}`;
  task=exercise("H={e,(12)} passes the conjugation test at h=e. Why is it still not normal?",["The h=e test is satisfied by every subgroup.","Choose h=(23) instead. Conjugation sends (12) to another transposition, so the set no longer equals H.","A normal subgroup must be invariant under conjugation by every group element. A₃ satisfies this condition and gives a quotient group of order two."]);
 }
 if(t==='irreducible'){
  const blocks=p.representation==='permutation'?[['A₁',1],['E',2]]:[[p.representation,dims[p.representation]]];blocks.forEach(([name,d],i)=>{const x=blocks.length===1?205:65+i*310;body+=`<rect x="${x}" y="85" width="245" height="155" rx="14" fill="${d===2?'#e5f1f6':'#f7ecd9'}" stroke="#91aeba"/>`+text(x+122,145,name,undefined,32)+text(x+122,195,`Common invariant subspaces: dimensions ${d}`);});
  html=`<h3>The character self-inner-product (squared norm) is ${fmt(r.characterNorm)}</h3><p>${math(String.raw`\langle\chi,\chi\rangle=\frac1{|G|}\sum_g|\chi(g)|^2=\sum_\alpha m_\alpha^2`)}. The current characters of the three classes are (${r.representationCharacters.map(fmt).join(', ')})，${r.irreducible?"gives 1, establishing irreducibility over the complex numbers.":"gives 2, with one copy each of A₁ and E."}</p><p>Matrix of the selected operation ${esc(names[p.g])} :</p>${matrix(r.selectedMatrix)}<p>Irreducibility requires no nontrivial common invariant subspace for the entire group. Diagonalizing one matrix does not decompose the whole representation: different operations generally have different eigenvector directions.</p>`;
  task=exercise("One reflection-type matrix in E has two eigenvectors. Why can E still be irreducible?",["Eigenvectors of a single operation are invariant under that operation alone.","Another group operation can mix those directions, so they do not define one-dimensional subspaces invariant under the entire group.","Using the character self-inner-product over the whole group gives 1 for E and 2 for the three-vertex permutation representation."]);
 }
 if(t==='schur'){
  const blocks=p.representation==='E'?[['E',p.a,2]]:[['A₁',p.a,1],['E',p.b,2]];blocks.forEach(([label,x,d],i)=>{const left=blocks.length===1?205:55+i*315;body+=`<rect x="${left}" y="90" width="260" height="145" rx="12" fill="#ecf4f8" stroke="#91abba"/>`+text(left+130,135,label,undefined,27)+text(left+130,185,`${fmt(x)} × I${d}`);});
  html=`<h3>Residual for commutation with all representation matrices:${fmt(r.commutatorResidual)}</h3><p>Schur's lemma restricts self-intertwiners to scalars in a finite-dimensional complex irreducible space ${math(String.raw`M=cI`)}. The current M ${r.scalar?"is a scalar on the entire representation space.":"is not a scalar on the full three-dimensional space, but is scalar separately on the A₁ and E blocks because this representation is reducible."}</p>${matrix(r.intertwiner)}<p>Intertwiners between inequivalent irreps vanish; equivalent copies can have nonzero intertwiners. If an irrep occurs repeatedly, commuting operators can mix copies in the multiplicity space. The entire isotypic component need not be a single scalar block.</p>`;
  task=exercise("For a≠b, M=aP₍A₁₎+bP₍E₎ commutes but is not proportional to the identity. Does this contradict Schur's lemma?",["The three-dimensional representation in this example is A₁⊕E, not an irrep.","Schur's lemma applies separately to the inequivalent A₁ and E subspaces and allows two different scalars.","Within a single E irrep, a commuting operator must be cI₂. Multiple equivalent E copies also require the multiplicity space to be considered."]);
 }
 if(t==='unitarity'){
  const sinv=inv2(r.S),points=Array.from({length:65},(_,i)=>[Math.cos(2*Math.PI*i/64),Math.sin(2*Math.PI*i/64)]),skewed=points.map(v=>sinv.map(row=>dot(row,v))),extent=Math.max(1,...skewed.map(v=>Math.hypot(...v))),path=(ps,cx)=>ps.map((v,i)=>`${i?'L':'M'}${cx+100*v[0]/extent},${170-100*v[1]/extent}`).join(' ');body+=`<path d="${path(points,170)}" fill="none" stroke="#287d9e" stroke-width="3"/><path d="${path(skewed,490)}" fill="none" stroke="#b56b38" stroke-width="3"/>`+text(170,35,"Standard orthonormal coordinates")+text(490,35,"Coordinates after the similarity transformation")+text(330,305,"Change the inner product to restore a unitary form of the same representation");
  html=`<h3>Group averaging gives a positive-definite inner product; a general similarity transformation need not be unitary</h3><p>${math(String.raw`D'(g)=S^{-1}D(g)S`)}. The unitarity residual over the full group in the ordinary Euclidean inner product is ${fmt(r.ordinaryResidual)}. Choosing ${math(String.raw`M=S^\dagger S`)} or ${math(String.raw`M_{\rm avg}=\frac1{|G|}\sum_g D'(g)^\dagger D'(g)`)} gives${math(String.raw`D'(g)^\dagger MD'(g)=M`)}, with residual ${fmt(r.metricResidual)}。</p><p>Factor the positive-definite M as ${math(String.raw`C^\dagger C=M`)}and change basis using ${math(String.raw`U(g)=CD'(g)C^{-1}`)} ; the full-group unitarity residual becomes ${fmt(r.unitaryResidual)}。</p>${table(["Current operation","Matrix in the nonorthogonal basis","New unitary matrix"],[[esc(names[p.g]),matrix(r.nonunitary),matrix(r.unitary)]])}<p>The theorem applies to finite-dimensional complex representations of finite groups. This example uses real matrices as a special case of complex matrices. Being equivalent to a unitary representation does not mean the original matrices are unitary in every coordinate system.</p>`;
  task=exercise("Why is the group-averaged metric positive definite and invariant under group operations?",["Every D(g) is invertible. For nonzero v, v†Mv=(1/|G|)Σg||D(g)v||²>0.","In D(h)†MD(h), multiplication rearranges the group elements being summed, leaving the sum unchanged.","A positive-definite metric has an invertible square root or Cholesky factor. Changing basis with it turns metric unitarity into ordinary unitarity."]);
 }
 if(t==='orthogonality'){
  const y0=160;body+=line(40,y0,630,y0,'#a9bdc8',1);r.terms.forEach((value,i)=>{const x=65+i*105,h=100*Math.abs(value);body+=`<rect x="${x-16}" y="${value>=0?y0-h:y0}" width="32" height="${Math.max(1,h)}" fill="${value>=0?'#297c9d':'#b56a3b'}"/>`+text(x,285,names[i],undefined,14)+text(x,35,fmt(value));});body+=text(330,320,`Sum ${fmt(r.total)}; theorem prediction ${fmt(r.expected)}`);
  html=`<h3>Orthogonality of matrix elements in standard unitary irreducible representations</h3><p>${math(String.raw`\sum_g D^\alpha_{ij}(g)^*D^\beta_{kl}(g)=\frac{|G|}{d_\alpha}\delta_{\alpha\beta}\delta_{ik}\delta_{jl}`)}。</p><p>Current selection (${esc(p.alpha)},${p.i+1},${p.j+1}) and (${esc(p.beta)},${p.k+1},${p.l+1}); contributions from the six group elements are shown above. The character inner product ${math(String.raw`\frac1{|G|}\sum_g\chi_\alpha(g)^*\chi_\beta(g)`)} is ${fmt(r.characterInner)}。</p><p>The declared standard orthonormal E basis is used here. Matrix elements after an arbitrary nonunitary similarity transform cannot be inserted directly into the same formula; characters remain similarity-invariant.</p>`;
  task=exercise("Keep α=β=E and select different matrix-element indices. When should the sum vanish?",["Both Kronecker conditions equal 1 only when i=k and j=l.","When both indices match, the result is |S₃|/dE=6/2=3. If either condition fails, it is 0.","The result also vanishes for inequivalent α and β. Distinguish the sum of matrix-element products from the character inner product already divided by group order."]);
 }
 if(t==='reduction'){
  ['A1','A2','E'].forEach((name,i)=>{const x=40+i*215,m=r.multiplicities[name];body+=`<rect x="${x}" y="90" width="190" height="145" rx="12" fill="${r.validCharacter?'#edf6f7':'#fff1e6'}" stroke="#a8bec8"/>`+text(x+95,136,name,undefined,25)+text(x+95,183,`Multiplicity ${fmt(m)}`);});body+=text(330,285,`Dimension reconstruction:${fmt(r.reconstructedDimension)}；χ(e)=${fmt(r.inputCharacters[0])}`);
  html=`<h3>${r.validCharacter?"Reduction gives nonnegative integer multiplicities":"This candidate character fails the nonnegative-integer multiplicity test"}</h3><p>${math(String.raw`m_\alpha=\frac16\sum_c n_c\chi_\alpha(c)^*\chi(c)`)}, with columns identity, transpositions, three-cycles and weights 1,3,2.</p>${table(["Irreducible representation","Three weighted terms","Multiplicity"],Object.entries(r.multiplicities).map(([name,m])=>[name,r.weightedTerms[name].map(fmt).join(' + '),fmt(m)]))}<p>Dimension reconstruction alone is insufficient: each multiplicity must also be a nonnegative integer. Currently, ${math(String.raw`\sum_\alpha m_\alpha d_\alpha`)}=${fmt(r.reconstructedDimension)}。</p><p>For the complete irrep table,${math(String.raw`1^2+1^2+2^2=6`)}; the 3 irreps equal the 3 conjugacy classes in number. Each irrep appears in the regular representation with multiplicity equal to its dimension.</p>`;
  task=exercise("What happens if the second entry of χ=(3,1,0) is treated as three separate classes and then weighted by 3 again?",["The second entry is the character of each transposition in one conjugacy class. Its class size, 3, is included once.","The correct class weights 1,3,2 give multiplicities A₁:1, A₂:0, E:1.","For an element-by-element sum, list 6 terms and omit class weights. The methods are equivalent but cannot be mixed."]);
 }
 if(t==='degeneracy'){
  const lo=Math.min(...r.levels.map(x=>x.energy))-.3,hi=Math.max(...r.levels.map(x=>x.energy))+.3,Y=e=>275-(e-lo)/(hi-lo)*220;r.levels.forEach((o,i)=>{const x=75+i*210;body+=line(x,Y(o.energy),x+135,Y(o.energy),i?'#277c9e':'#b36a38',5)+text(x+67,Y(o.energy)-16,o.basis)+text(x+67,Y(o.energy)+28,fmt(o.energy));});
  html=`<h3>${r.fullSymmetry?"H preserves full S₃ symmetry":"The ε term breaks full S₃ symmetry"}</h3><p>${math(String.raw`H=aP_{A_1}+bP_E+\epsilon uu^T`)}, with full-group commutator residual ${fmt(r.commutatorResidual)}。${r.protectedE?"The two partners within E have the same energy and form a symmetry-protected doublet.":"The u and v energies are b+ε and b, respectively; the E partners are generally split now."}${r.accidentalThreefold?"Here a=b, so A₁ and E coincide as well, giving an additional accidental threefold degeneracy.":''}</p><p>An irrep's dimension gives the symmetry-protected dimension of the corresponding energy multiplet. An arbitrary reducible representation's total dimension is not the degeneracy of a single level. Equivalent copies can mix in multiplicity space, with a Hamiltonian generally acting as ${math(String.raw`I_d\otimes K_m`)}; distinct multiplicity-space eigenvalues each retain d-fold degeneracy, without necessarily making one d×m-fold level.</p>`;
  task=exercise("Set a=b, then take ε≠0. Can every coincidence be attributed to a three-dimensional irrep?",["The three-dimensional permutation representation reduces to A₁⊕E. This model has no three-dimensional irrep.","At ε=0, the E doublet is protected by S₃. Setting a=b makes A₁ and E coincide accidentally, giving threefold degeneracy.","For ε≠0 the full-group commutation relation is broken and the E partners can split. Remaining energy coincidences require individual checks; the matrix dimension alone is insufficient."]);
 }
 return {plot:svg("Interactive S₃ group-theorem illustration",body),html,exercise:task,data:r};
}
export function theoremScene(experiment,params={}){return scene(experiment,{...defaults[experiment],...params});}

export async function renderGroupTheoremsView({container,selection={},run,onNavigate=()=>{}}){
 let theme=theoremThemes.some(t=>t.id===selection.experiment)?selection.experiment:'rearrangement',state={...defaults[theme]},revision=0,busy=false,status='',pythonResult=null;
 container.innerHTML='<article class="gt-course"></article>';const root=container.firstElementChild,current=()=>container.isConnected!==false&&container.firstElementChild===root,payload=()=>({experiment:theme,...state});
 function update(){const out=scene(theme,state);root.querySelector('.gt-preview').innerHTML=out.plot+out.html;root.querySelector('.gt-questions').innerHTML=out.exercise;root.querySelectorAll('[data-output]').forEach(el=>el.textContent=state[el.dataset.output]);latest={tool:'group_theorems_preview',input:payload(),result:{...out.data,computation:'deterministic JavaScript finite-group preview'}};}
 function draw(){root.innerHTML=`<header class="gt-hero"><span>Group-theorem workshop</span><h2>Use one ${math(String.raw`S_3`)} model to connect nine theorems and applications</h2><p>Start from six permutations and follow conjugacy, representations, and physical degeneracy. Real example matrices are regarded as matrices over the complex numbers.</p></header><nav class="gt-tabs" aria-label="Group theorems and applications">${theoremThemes.map(t=>`<button type="button" data-theme="${t.id}" aria-pressed="${t.id===theme}">${t.title}</button>`).join('')}</nav><div class="gt-workspace"><aside class="gt-controls"><h3>Select and calculate</h3>${controls(theme,state)}<button type="button" class="primary" data-action="python" ${busy||!run?'disabled':''}>${busy?"Checking with Python…":"Check with browser Python"}</button><p class="gt-status" role="status">${esc(status||"Predict first, then inspect the calculation and theorem result.")}</p></aside><section class="gt-preview" aria-live="polite"></section></div><div class="gt-questions"></div><details class="gt-python"><summary>Python data and condition checks</summary><pre>${pythonResult?esc(JSON.stringify(pythonResult,null,2)):"After checking, results for the current input appear here."}</pre></details><footer><a href="#classroom/foundations?module=demos">Foundational demonstrations</a> · <a href="#classroom/foundations?module=mini">Advanced symmetry mini-experiments</a> · <a href="docs/group-theorems.md">Teaching models and conventions</a></footer>`;update();}
 function changed(e){const key=e.target.dataset.param;if(!key)return;revision++;state[key]=Number.isFinite(Number(e.target.value))?Number(e.target.value):e.target.value;if(theme==='orthogonality'){for(const q of ['i','j'])state[q]=Math.min(state[q],dims[state.alpha]-1);for(const q of ['k','l'])state[q]=Math.min(state[q],dims[state.beta]-1);}pythonResult=null;status="Input changed. Check the current conclusion again.";if(e.target.tagName==='SELECT')draw();else{update();root.querySelector('.gt-status').textContent=status;}}
 root.addEventListener('input',e=>{if(e.target.tagName!=='SELECT')changed(e);});root.addEventListener('change',changed);
 root.addEventListener('click',async e=>{const tab=e.target.closest('[data-theme]');if(tab){revision++;theme=tab.dataset.theme;state={...defaults[theme]};status='';pythonResult=null;onNavigate({experiment:theme});draw();return;}if(e.target.closest('[data-action]')?.dataset.action==='python'&&run&&!busy){const requestedRevision=revision,input=payload();busy=true;status="Checking the current finite-group model…";draw();try{const result=await run('group_theorems',input);if(!current()||requestedRevision!==revision)return;pythonResult=result;status=result?.validCharacter===false?"Python checked this candidate character: it fails the nonnegative-integer multiplicity condition.":result?.checks?.passed===false?"Python checks failed. Inspect the input and data.":"Python check complete.";draw();latest={tool:'group_theorems',input,result};}catch(error){if(current()&&requestedRevision===revision){status="Python check did not complete:"+error.message;draw();}}finally{busy=false;if(current()){const b=root.querySelector('[data-action="python"]');b.disabled=false;b.textContent="Check with browser Python";}}}});
 draw();
}
